const candidateSkin = process.env.MX_TEST_SKIN || 'style2';
const{chromium}=require(process.env.MX_PLAYWRIGHT_MODULE||'playwright-core');const fs=require('node:fs');
(async()=>{const b=await chromium.launch({executablePath:process.env.MX_CHROME||'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',headless:true});const p=await b.newPage({viewport:{width:1100,height:1200}}),errors=[],results=[];p.on('pageerror',e=>errors.push(String(e)));const out=process.env.MX_OUTPUT_DIR||'docs/styles/'+candidateSkin+'/implementation/content-capacity';fs.mkdirSync(out,{recursive:true});const cases=[];for(const layout of ['original','balanced','classic','oval'])for(const scene of ['squid-join','sidepots-long','board-dual-turn'])cases.push({layout,scene,width:440,height:782});for(const [width,height]of [[375,500],[320,400]])for(const scene of ['squid-join','sidepots-long','board-dual-turn'])cases.push({layout:'original',scene,width,height});cases.push({layout:'original',scene:'squid-join',width:440,height:956},{layout:'balanced',scene:'sidepots-long',width:844,height:440,orientation:'auto'});
for(const c of cases){await p.goto((process.env.MX_AUDIT_URL||'http://127.0.0.1:5183')+'/tests/fixtures/layout-audit.html?'+new URLSearchParams({skin:candidateSkin,seats:8,action:1,bb:1,...c}));await p.locator('#audit-stage[data-ready=true]').waitFor({timeout:60000});const metrics=await p.evaluate(()=>{const r=e=>{const b=e.getBoundingClientRect();return {x:b.x,y:b.y,w:b.width,h:b.height,right:b.right,bottom:b.bottom}};const pool=document.querySelector('.mx-pools'),sides=document.querySelector('.mx-side-pools'),info=document.querySelector('.mx-room-info'),boards=[...document.querySelectorAll('.mx-board .mx-public-slot')].filter(e=>e.checkVisibility()).map(r),hero=document.querySelector('.mx-seat-mine .mx-avatar'),sideItems=[...sides.children].map(r),rows=[...pool.querySelectorAll('.mx-pool-item')];const maxBoard=Math.max(...boards.map(b=>b.bottom)),minBoard=Math.min(...boards.map(b=>b.y));return {pool:r(pool),sides:r(sides),sideItems,info:{...r(info),client:info.clientHeight,scroll:info.scrollHeight,text:info.textContent},hero:r(hero),minBoard,maxBoard,sideAlign:getComputedStyle(sides).justifyContent,rows:rows.map(e=>({...r(e),client:e.clientWidth,scroll:e.scrollWidth})),boardCount:boards.length}});
const id=`${c.layout}-${c.scene}-${c.width}x${c.height}`;await p.locator('#audit-stage').screenshot({path:out+'/'+id+'.png'});
const scroll=await p.evaluate(()=>{const root=document.querySelector('.mx-pools'),sides=document.querySelector('.mx-side-pools'),scroller=getComputedStyle(sides).display==='contents'?root:sides;scroller.scrollLeft=scroller.scrollWidth;const last=scroller.querySelector('.mx-pool-item:last-child')||scroller.lastElementChild;const rect=last.getBoundingClientRect(),sr=scroller.getBoundingClientRect();const info=document.querySelector('.mx-room-info');info.scrollTop=info.scrollHeight;return {lastVisible:rect.left>=sr.left-1&&rect.right<=sr.right+1,infoEnd:Math.abs(info.scrollTop+info.clientHeight-info.scrollHeight)<=1}});results.push({case:c,metrics,scroll,errors:errors.splice(0)});
}
fs.writeFileSync(out+'/results.json',JSON.stringify(results,null,2));const failures=results.flatMap(r=>{const m=r.metrics,f=[];if(r.errors.length)f.push('page errors');if(r.case.scene==='squid-join'&&r.case.height>=734&&m.info.scroll>m.info.client+1)f.push('room clipped');if(m.rows.some(x=>x.scroll>x.client+2))f.push('pool value clipped');if(!r.scroll.infoEnd)f.push('room unreachable');if(!r.case.orientation&&m.info.y<m.maxBoard-1)f.push('info overlaps board');if(!r.case.orientation&&m.pool.bottom>m.minBoard-1)f.push('pool overlaps board');if(m.sideItems.length&&m.sideAlign!=='flex-start'&&r.case.height>=734&&!r.case.orientation)f.push('side pools not left aligned');return f.length?[{case:r.case,failures:f}]:[]});console.log({cases:results.length,failures});if(failures.length)process.exitCode=1;await b.close()})();
